 const pose=await page.locator('canvas').getAttribute('data-camera-position'),target=await page.locator('canvas').getAttribute('data-camera-target'),box=(await page.locator('canvas').boundingBox())!;await page.mouse.click(box.x+box.width*.52,box.y+box.height*.5);await expect(page.locator('.pv-building-panel')).toBeVisible();expect(await page.locator('canvas').getAttribute('data-camera-position')).toBe(pose);expect(await page.locator('canvas').getAttribute('data-camera-target')).toBe(target);
