test('source-aligned road map and locked orthographic elevation fit both sides',async({page})=>{await page.goto('/areas/tocho/gallery');await ready(page);const roads=(await(await page.request.get('/assets/pv-adopted-20261029/roads.json')).json()).roads;expect(roads).toHaveLength(184);expect(roads.every(r=>r.sourceRoadId&&r.heightSamples.length>=5)).toBeTruthy();const c=page.locator('canvas'),r=(await c.boundingBox())!,{data,info}=await sharp(await c.screenshot()).raw().toBuffer({resolveWithObject:true});let point:number[]=[];for(let y=130;y<info.height-50&&!point.length;y++)for(let x=300;x<info.width-100;x++){const i=(y*info.width+x)*info.channels;if(data[i]>170&&data[i]-data[i+1]>40&&data[i+2]-data[i+1]>15){point=[x,y];break;}}expect(point.length).toBe(2);await page.mouse.click(r.x+point[0],r.y+point[1]);await expect(c).toHaveAttribute('data-view','street');await page.goto('/areas/tocho/gallery?road=road-4&side=left');await ready(page);await expect(c).toHaveAttribute('data-projection','orthographic');const left=JSON.parse(await c.getAttribute('data-visible-buildings')||'[]'),pose=await c.getAttribute('data-camera-position'),target=await c.getAttribute('data-camera-target');await page.mouse.move(600,450);await page.mouse.down();await page.mouse.move(720,490);await page.mouse.up();await page.mouse.wheel(0,-600);expect(await c.getAttribute('data-camera-position')).toBe(pose);expect(await c.getAttribute('data-camera-target')).toBe(target);await page.getByRole('tab',{name:'右側の建物'}).click();const right=JSON.parse(await c.getAttribute('data-visible-buildings')||'[]');expect(left.length).toBeGreaterThan(0);expect(right.length).toBeGreaterThan(0);expect(left.filter(x=>right.includes(x))).toEqual([]);await page.screenshot({path:'test-results/revision-street.png'});});
test('walk height, faster travel, reversed mouse look and building selection without teleport',async({page})=>{await page.goto('/areas/tocho/walk?road=road-4');await ready(page);const c=page.locator('canvas');const before=(await c.getAttribute('data-camera-position'))!.split(',').map(Number);expect(Math.abs(before[1]-Number(await c.getAttribute('data-ground-height'))-3.4)).toBeLessThan(.01);await c.click({position:{x:600,y:400}});await page.keyboard.down('w');await page.waitForTimeout(600);await page.keyboard.up('w');const after=(await c.getAttribute('data-camera-position'))!.split(',').map(Number);expect(Math.hypot(after[0]-before[0],after[2]-before[2])).toBeGreaterThan(3);const target=(await c.getAttribute('data-camera-target'))!.split(',').map(Number),heading=Math.atan2(target[0]-after[0],-(target[2]-after[2]));await page.mouse.move(700,400);await page.mouse.down();await page.mouse.move(780,400,{steps:10});await page.mouse.up();const next=(await c.getAttribute('data-camera-target'))!.split(',').map(Number),angle=Math.atan2(next[0]-after[0],-(next[2]-after[2])),delta=Math.atan2(Math.sin(angle-heading),Math.cos(angle-heading));expect(delta).toBeLessThan(0);const pose=await c.getAttribute('data-camera-position');let selected=false;const r=(await c.boundingBox())!;for(const y of [.3,.5,.7]){for(const x of [.25,.4,.6,.8]){await page.mouse.click(r.x+r.width*x,r.y+r.height*y);if(await page.locator('.pv-building-panel').count()){selected=true;break;}}if(selected)break;}expect(selected).toBeTruthy();expect(await c.getAttribute('data-camera-position')).toBe(pose);await page.screenshot({path:'test-results/revision-walk.png'});});
